const wheel = document.getElementById('radialWheel');
const svg = document.getElementById('spokesSvg');
const panelIndex = document.getElementById('panelIndex');
const panelBody = document.getElementById('panelBody');
const panelBadge = document.getElementById('panelBadge');
const panelTitle = document.getElementById('panelTitle');
const panelDesc = document.getElementById('panelDesc');
const panelCta = document.getElementById('panelCta');
const panelProgress = document.getElementById('panelProgress');

const CENTER = 310;
const RADIUS = 200;
const N = services.length;
const INNER_GAP = 100; /* space cleared around the logo */
const OUTER_GAP = 70;  /* space cleared before reaching each icon */

let nodes = [];
let spokeLines = [];
let activeIndex = 0;
let autoTimer = null;
let progressTimer = null;
const AUTO_INTERVAL = 4000;

function positionNodes() {
  const W = wheel.clientWidth || 550;
  const scale = W / 620;
  nodes.forEach((node, i) => {
    const angle = (-90 + (360 / N) * i) * (Math.PI / 180);
    let x = CENTER + RADIUS * Math.cos(angle);
    let y = CENTER + RADIUS * Math.sin(angle);
    
    // Shift specific nodes to prevent collision
    if (i === 1) { // Continental Bridge (right side)
      x += 20;
    } else if (i === 5) { // Wealth Concierge (left side)
      x -= 20;
    }
    
    node.style.left = (x * scale) + 'px';
    node.style.top = (y * scale) + 'px';
  });
}
window.addEventListener('resize', positionNodes);

function buildWheel(){
  services.forEach((service, i) => {
    const angle = (-90 + (360 / N) * i) * (Math.PI / 180);
    let x = CENTER + RADIUS * Math.cos(angle);
    let y = CENTER + RADIUS * Math.sin(angle);
    
    // Shift specific nodes to prevent collision
    if (i === 1) { // Continental Bridge (right side)
      x += 20;
    } else if (i === 5) { // Wealth Concierge (left side)
      x -= 20;
    }

    const dx = x - CENTER, dy = y - CENTER;
    const dist = Math.sqrt(dx * dx + dy * dy);
    const ux = dx / dist, uy = dy / dist;

    const startX = CENTER + ux * INNER_GAP;
    const startY = CENTER + uy * INNER_GAP;
    
    // Adjust outer gap for shifted nodes to keep arrows clear of labels
    let outerGap = OUTER_GAP;
    if (i === 1 || i === 5) {
      outerGap = 90;
    }
    const endX = x - ux * outerGap;
    const endY = y - uy * outerGap;

    const line = document.createElementNS('http://www.w3.org/2000/svg','line');
    line.setAttribute('x1', startX);
    line.setAttribute('y1', startY);
    line.setAttribute('x2', endX);
    line.setAttribute('y2', endY);
    line.setAttribute('class','spoke-line');
    line.setAttribute('marker-end','url(#arrowHead)');
    svg.appendChild(line);
    spokeLines.push(line);

    const node = document.createElement('div');
    node.className = 'service-node';
    node.style.transform = 'translate(-50%, -50%)';
    node.style.animation = `nodeIn 0.5s ease ${0.15 + i * 0.08}s backwards`;
    node.setAttribute('tabindex', '0');
    node.setAttribute('role', 'button');
    node.setAttribute('aria-label', `Show ${service.title} details`);
    node.innerHTML = `<img src="${service.icon}" alt="${service.title} icon"><span class="node-label">${service.title}</span>`;
    node.addEventListener('click', () => selectService(i, true));
    node.addEventListener('keydown', (e) => {
      if(e.key === 'Enter' || e.key === ' '){
        e.preventDefault();
        selectService(i, true);
      }
    });
    wheel.appendChild(node);
    nodes.push(node);
  });

  positionNodes();

  services.forEach(() => {
    const dot = document.createElement('div');
    dot.className = 'progress-dot';
    dot.innerHTML = '<span class="fill"></span>';
    panelProgress.appendChild(dot);
  });
}

function addArrowMarker(){
  const defs = document.createElementNS('http://www.w3.org/2000/svg','defs');
  defs.innerHTML = `
    <marker id="arrowHead" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <path d="M0,0 L10,5 L0,10 z" fill="#007B9E" fill-opacity="0.55"></path>
    </marker>
    <marker id="arrowHeadActive" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse">
      <path d="M0,0 L10,5 L0,10 z" fill="#00AEEF"></path>
    </marker>`;
  svg.appendChild(defs);
}

function selectService(index, isManual, instant){
  activeIndex = index;
  const service = services[index];

  nodes.forEach((n, i) => n.classList.toggle('active', i === index));
  spokeLines.forEach((l, i) => l.classList.toggle('active', i === index));

  const applyContent = () => {
    panelIndex.textContent = String(index + 1).padStart(2,'0') + ' / ' + String(N).padStart(2,'0');
    panelBadge.innerHTML = service.badge;
    panelTitle.textContent = service.title;
    panelDesc.textContent = service.desc;

    panelCta.href = `service-detail.html?service=${service.anchor}`;

    panelCta.setAttribute('aria-label', `Know more about ${service.title}`);
    panelBody.classList.remove('panel-content-fade');
  };

  if(instant){
    applyContent();
  } else {
    panelBody.classList.add('panel-content-fade');
    setTimeout(applyContent, 180);
  }

  resetProgressDots(index);

  if(isManual){
    restartAuto();
  }
}

function resetProgressDots(index){
  const dots = panelProgress.querySelectorAll('.progress-dot');
  dots.forEach((dot, i) => {
    const fill = dot.querySelector('.fill');
    dot.classList.remove('filling');
    fill.style.transition = 'none';
    if(i < index){
      dot.classList.add('done');
      fill.style.width = '100%';
    } else {
      dot.classList.remove('done');
      fill.style.width = '0%';
    }
  });

  clearTimeout(progressTimer);
  requestAnimationFrame(() => {
    const activeDot = dots[index];
    const activeFill = activeDot.querySelector('.fill');
    activeDot.classList.add('filling');
    activeFill.style.transition = `width ${AUTO_INTERVAL}ms linear`;
    requestAnimationFrame(() => { activeFill.style.width = '100%'; });
  });
}

function nextService(){
  const next = (activeIndex + 1) % N;
  selectService(next, false);
}

function startAuto(){
  autoTimer = setInterval(nextService, AUTO_INTERVAL);
}

function restartAuto(){
  clearInterval(autoTimer);
  startAuto();
}

addArrowMarker();
buildWheel();
selectService(0, false, true);
startAuto();